"""Summarize saved measurements without inventing completion or test evidence."""
import json
from pathlib import Path
import pandas as pd

BASE = Path(__file__).resolve().parent
if __name__ == "__main__":
    completed = json.loads((BASE / "trained_expanded/training_completed.json").read_text())
    assert completed["status"] == "completed"
    external = json.loads((BASE / "external_test/evaluation.json").read_text())
    regression = json.loads((BASE / "external_test/user_bottle_regression.json").read_text()) if (BASE / "external_test/user_bottle_regression.json").exists() else None
    metrics = pd.read_csv(BASE / "trained_expanded/baseline_vs_finetuned.csv")
    counts = pd.read_csv(BASE / "data/expanded/class_counts.csv")
    lines = ["# EcoSort Expanded Local Run", "", "## Measured Data and Training", "", "Raw source pool: 167,285 rows (147,285 indexed Garbage265 images plus the original selected 20,000). Retained after audit: 147,303. Train: 117,893; validation: 14,698; test: 14,712. The approximate 80/10/10 split differs from the original proposal's 70/15/15, following the revised training-size request.", "", f"Actual training and internal evaluation runtime: {completed['seconds'] / 60:.2f} minutes. Selected by validation macro-F1: {completed['selected']}. Full logs and completion record are in trained_expanded/. Every training image is visited per epoch; held-out images never update weights.", "", "```text", metrics.to_string(index=False), "```", "", "## Class Counts", "", "```text", counts.to_string(index=False), "```", "", "## External Test", "", f"Ten externally sourced photos were frozen and duplicate-checked before prediction. Correct top-1 classifications: {external['correct']}/10 ({external['top1_accuracy']:.0%}). Manual review rate: {external['manual_review_rate']:.0%}. Accepted count: {external['accepted_count']}; accepted accuracy: {external['accepted_accuracy']}. This small convenience sample is not a population accuracy estimate.", "", "Per-image expected and predicted labels, sources, licences, timing and review status: external_test/predictions.csv. Visual results: external_test/results_gallery.jpg. Selection was not changed after seeing predictions. One original keyboard candidate was rejected before prediction because of a perceptual near match.", "", "## Earlier Bottle Regression", "", json.dumps(regression, indent=2) if regression else "Original upload not available; not tested.", "", "## Rule and Interface Scope", "", "Material prediction remains separate from item-confirmed disposal guidance. City of Sydney yellow/red/green/food services and NSW EPA problem-waste routes include conditions, official links and verification dates. Uncertain unconfirmed images require review. The model cannot inspect hidden contents, contamination or battery damage. Rule checks cover 1,156 valid input combinations. Browser and camera results must be read from ui_verification.json when present, not inferred from backend tests.", "", "## Comparison with Original Proposal", "", "Implemented: grouped image preparation, frozen MobileNetV3 baseline, partial fine-tuning, identical model comparison partitions, validation-only checkpoint/threshold selection, class metrics/confusion matrices, local upload/camera interface, conditional source-linked rules and manual-review flags.", "", "Changed by revised scope: a larger multi-source dataset replaces the specific TrashNet + TACO training plan; TACO crops were not included. Approximately 80/10/10 replaces 70/15/15. The current single-item software does not claim municipal deployment or embedded hardware.", "", "Not completed from the original proposal: 50-100 independently collected local Sydney photos; validated batch unacceptable-item proportions with unresolved coverage; contaminant precision/recall against manually confirmed local item conditions; LLM source-linked summaries and their numerical/grounding comparison with fixed templates; total workflow timing including cropping and review; final team report/demo and operational validation.", "", "## Limits and Provenance", "", "The dataset includes noisy labels, mixed-material objects, product shots and some non-photographic images. Only selected contact sheets and definite errors were manually reviewed, not every image. Exact/pixel and perceptual grouping reduce leakage but do not prove full independence. More images do not guarantee better real-world accuracy. Class weights are smoothed and capped, not a promise of zero bias. Keep test photos out of future tuning unless a new independent test panel is collected.", "", "Sources: [Garbage265 publisher](https://www.modelscope.cn/datasets/tany0699/garbage265), [archive mirror](https://huggingface.co/datasets/fritz1024/garbage265-classification), [City of Sydney recycling](https://www.cityofsydney.nsw.gov.au/waste-recycling-services/recycle-household-items), [NSW EPA problem waste](https://www.epa.nsw.gov.au/Your-environment/Recycling-and-reuse/household-recycling-overview/community-recycling-centres). Individual external-photo attribution is recorded in the frozen manifest. Publisher licensing does not establish rights to every constituent photo; do not redistribute raw images without reviewing source rights.", ""]
    ui_path = BASE / "ui_verification.json"
    if ui_path.exists():
        ui = json.loads(ui_path.read_text())
        lines.extend(["## Measured Interface Verification", "", f"English built-in upload prompt: {ui['english_builtin_upload_prompt']}. Camera received {ui['camera_video_width']} x {ui['camera_video_height']} frames, captured a photo and completed prediction. Camera scene accuracy was not assessed; this was an unlabeled I/O smoke test. Camera closed after the test: {ui['camera_closed_after_test']}.", "", "The original bottle was uploaded through the actual webpage. A simulated empty-bottle confirmation produced the conditional yellow-lid route without changing the raw prediction or removing its review flag. Removing the image reset the confirmation and outputs. The final displayed bottle remains unconfirmed. See expanded_app_verified.png and ui_verification.json.", "", "## Readiness Conclusion", "", "Not ready for reliable autonomous classification: the fixed external panel scored only 5/10, although all five errors were flagged for review. Four accepted predictions were correct, but four cases cannot establish a reliable accepted accuracy. The internal/public-test improvement does not establish local Sydney performance. Next work should prioritize curated real photographs, ambiguous-category mapping and a new independent local evaluation, not merely increasing image count or tuning on these ten test images.", ""])
    (BASE / "EXPANDED_RUN_REPORT.md").write_text("\n".join(lines))
    print(BASE / "EXPANDED_RUN_REPORT.md")
